declare(strict_types=1);

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

/**
 * Add only Notifications surfaces to the existing NC34/35 fixtures, using the verbatim, hash-checked source pins.
 * Usage: php tests/fixtures/nextcloud-api/generate-notifications.php <34|35> [fixture output directory].
 * No network, source execution, server, SQL or unrelated fixture regeneration is involved.
 */
require __DIR__ . '/../../../vendor/autoload.php';
$major = $argv[1] ?? '';
$pins = json_decode((string)file_get_contents(__DIR__ . '/../notifications-native/sources.json'), true, 512, JSON_THROW_ON_ERROR)['versions'];
if (!isset($pins[$major])) throw new RuntimeException('Expected an Notifications source pin: 34 or 35.');
$target = ($argv[2] ?? __DIR__) . '/' . $major . '.php';
$tree = sys_get_temp_dir() . '/mcp-notifications-api-' . bin2hex(random_bytes(6));
mkdir($tree . '/apps/notifications/lib', recursive: true);
try {
	foreach ($pins[$major] as $file => $pin) {
		$source = __DIR__ . '/../notifications-native/' . $major . '/' . $file;
		if (hash_file('sha256', $source) !== $pin['sha256']) throw new RuntimeException('Notifications source SHA256 mismatch: ' . $file);
		copy($source, $tree . '/apps/notifications/lib/' . $file);
	}
	mkdir($tree . '/lib/public/Notification', recursive: true);
	copy(__DIR__ . '/../notifications-native/' . $major . '/INotification.php', $tree . '/lib/public/Notification/INotification.php');
	$fixture = require $target;
	$parser = new SourceParser($tree);
	foreach (['OCA\\Notifications\\Handler', 'OCP\\Notification\\INotification'] as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) throw new RuntimeException('Missing pinned Notifications surface: ' . $class);
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$original = (string)file_get_contents($target);
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// Notifications surfaces generated[^\n]*\n~', '', $header);
	$header .= "// Notifications surfaces generated by generate-notifications.php; exact source URLs and SHAs in notifications-native/sources.json.\n";
	FixtureFile::write($target, $header, $fixture);
	echo 'Generated Notifications Handler surface for NC' . $major . "\n";
} finally {
	$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
	foreach ($files as $file) $file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
	rmdir($tree);
}
